// B498: the Latin letters Go collates like String.prototype.localeCompare.
// A letter is kept when its NFD form is one ASCII letter and combining marks
// (U+0300-U+036F). Marks get their secondary rank from the ICU order of "a"+mark.
const letters = [];
const marks = new Set();
for (const [lo, hi] of [[0xc0, 0x24f], [0x1e00, 0x1eff]]) {
  for (let cp = lo; cp <= hi; cp++) {
    const ch = String.fromCodePoint(cp);
    const nfd = ch.normalize('NFD');
    if (nfd === ch || !/^[A-Za-z][̀-ͯ]+$/.test(nfd)) continue;
    letters.push([cp, nfd]);
    for (const m of nfd.slice(1)) marks.add(m);
  }
}
const sorted = [...marks].sort((x, y) => ('a' + x).localeCompare('a' + y));
const rank = new Map();
let r = 0;
sorted.forEach((m, i) => {
  if (i === 0 || ('a' + sorted[i - 1]).localeCompare('a' + m) !== 0) r++;
  rank.set(m, r);
});
let go = '// Code generated by testdata/b498_collate.js from Node ' + process.version + ' (ICU ' + process.versions.icu + '); DO NOT EDIT.\n\npackage gatecheck\n\n';
go += '// latinMarks is the ICU secondary rank of each combining mark, from the\n// order of "a"+mark under localeCompare (1 is the lightest).\nvar latinMarks = map[rune]int{\n';
for (const m of [...marks].sort()) go += `\t0x${m.codePointAt(0).toString(16).toUpperCase().padStart(4, '0')}: ${rank.get(m)},\n`;
go += '}\n\n// latinLetters is the NFD form of each precomposed Latin letter Go collates.\nvar latinLetters = map[rune]string{\n';
for (const [cp, nfd] of letters) {
  go += `\t0x${cp.toString(16).toUpperCase().padStart(4, '0')}: "${nfd[0]}${[...nfd.slice(1)].map((m) => '\\u' + m.codePointAt(0).toString(16).padStart(4, '0')).join('')}",\n`;
}
go += '}\n';
process.stdout.write(go);
